        for t in node.get("pre_actions") or []:
            fn = (t or {}).get("function") or {}
            if fn.get("handler") == "__function__:code_exec":
                out.append((key, str(((fn.get("parameters") or {}).get("properties") or {}).get("code", {}).get("default") or "")))
    return out


